src/mios/contracts/clocks.py:
"""Four-clock contract and injectable clocks.

Laws: four distinct clocks (2); knowledge time never fabricated (3); deterministic replay (11).
"""
from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from typing import Optional

from .timestamps import NaiveTimestampError, PointInTimeTimestamp


class KnowledgeTimeFabricationError(ValueError):
    """ingested_at would be fabricated rather than genuinely captured (Law 3)."""


@dataclass(frozen=True)
class FourClocks:
    """event_time / published_at / ingested_at / system_time, all semantically distinct."""

    event_time: PointInTimeTimestamp
    ingested_at: PointInTimeTimestamp
    system_time: PointInTimeTimestamp
    published_at: Optional[PointInTimeTimestamp] = None
    ingested_at_genuine_capture: bool = True

    def __post_init__(self) -> None:
        if not self.ingested_at_genuine_capture:
            raise KnowledgeTimeFabricationError(
                "ingested_at may only be set to an instant at which this system genuinely captured the item; "
                "archive publication time must not be copied into receipt time"
            )

    def to_canonical_dict(self) -> dict:
        return {
            "schema": "mios.clocks",
            "event_time": self.event_time.to_canonical_dict(),
            "published_at": self.published_at.to_canonical_dict() if self.published_at else None,
            "ingested_at": self.ingested_at.to_canonical_dict(),
            "system_time": self.system_time.to_canonical_dict(),
        }


class DeterministicClock:
    """Injectable clock producing a reproducible sequence of UTC instants (tests / replay)."""

    def __init__(self, start: datetime, step_seconds: float = 1.0) -> None:
        if start.tzinfo is None or start.tzinfo.utcoffset(start) is None:
            raise NaiveTimestampError("DeterministicClock requires a timezone-aware start instant")
        self._current = start.astimezone(timezone.utc)
        self._step = timedelta(seconds=step_seconds)

    def now(self) -> datetime:
        value = self._current
        self._current = self._current + self._step
        return value

src/mios/contracts/hashing.py:
"""Canonical serialization and hashing.

Identical contract values must serialize to identical bytes and hashes (Law 11).
Decimals serialize as exact strings; datetimes serialize as UTC ISO-8601; naive datetimes are rejected.
"""
from __future__ import annotations

import hashlib
import json
from datetime import datetime, timezone
from decimal import Decimal
from enum import Enum
from typing import Any


def _canonical_default(obj: Any) -> Any:
    if isinstance(obj, Decimal):
        return {"__decimal__": format(obj, "f")}
    if isinstance(obj, datetime):
        if obj.tzinfo is None or obj.tzinfo.utcoffset(obj) is None:
            raise ValueError("naive datetime cannot be canonically serialized")
        return {"__datetime_utc__": obj.astimezone(timezone.utc).isoformat()}
    if isinstance(obj, Enum):
        return obj.value
    if isinstance(obj, bytes):
        return {"__bytes_sha256__": hashlib.sha256(obj).hexdigest()}
    if hasattr(obj, "to_canonical_dict"):
        return obj.to_canonical_dict()
    raise TypeError(f"type {type(obj).__name__} has no canonical serialization")


def canonical_json(data: Any) -> bytes:
    """Deterministic canonical JSON: sorted keys, minimal separators, UTF-8."""
    return json.dumps(
        data, default=_canonical_default, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def contract_hash(data: Any) -> str:
    return sha256_hex(canonical_json(data))

src/mios/contracts/licensing.py:
"""Machine-enforceable license policy (Laws 6/7: rights are data; deny by default)."""
from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Optional


class LicenseUse(Enum):
    INTERNAL_RESEARCH = "internal_research"
    DERIVED_SIGNALS = "derived_signals"
    REDISTRIBUTION = "redistribution"
    PUBLIC_DISPLAY = "public_display"
    TEST_FIXTURE = "test_fixture"


class LicenseViolation(PermissionError):
    """A use is not permitted by the governing license policy."""


@dataclass(frozen=True)
class LicensePolicy:
    license_id: str
    internal_research: bool = False
    derived_signals: bool = False
    redistribution: bool = False
    public_display: bool = False

    def permits(self, use: LicenseUse) -> bool:
        if use is LicenseUse.TEST_FIXTURE:
            return True
        return {
            LicenseUse.INTERNAL_RESEARCH: self.internal_research,
            LicenseUse.DERIVED_SIGNALS: self.derived_signals,
            LicenseUse.REDISTRIBUTION: self.redistribution,
            LicenseUse.PUBLIC_DISPLAY: self.public_display,
        }[use]

    def to_canonical_dict(self) -> dict:
        return {
            "schema": "mios.license_policy",
            "license_id": self.license_id,
            "internal_research": self.internal_research,
            "derived_signals": self.derived_signals,
            "redistribution": self.redistribution,
            "public_display": self.public_display,
        }


def enforce_license(policy: Optional[LicensePolicy], use: LicenseUse) -> None:
    """Missing policy denies every non-test use."""
    if policy is None:
        if use is LicenseUse.TEST_FIXTURE:
            return
        raise LicenseViolation(f"no license policy attached: use '{use.value}' denied by default")
    if not policy.permits(use):
        raise LicenseViolation(f"license '{policy.license_id}' does not permit use '{use.value}'")

