"""Provenance contracts: evidence roots and edges (Laws 4/6). Append-only by construction."""
from __future__ import annotations

from dataclasses import dataclass

from .timestamps import PointInTimeTimestamp


@dataclass(frozen=True)
class EvidenceRoot:
    """Immutable original bytes, identified by their SHA-256, captured at a genuine instant."""

    raw_payload_sha256: str
    source_id: str
    captured_at: PointInTimeTimestamp

    def __post_init__(self) -> None:
        if len(self.raw_payload_sha256) != 64:
            raise ValueError("evidence root must reference a sha-256 hex digest of original bytes")

    def to_canonical_dict(self) -> dict:
        return {
            "schema": "mios.evidence_root",
            "raw_payload_sha256": self.raw_payload_sha256,
            "source_id": self.source_id,
            "captured_at": self.captured_at.to_canonical_dict(),
        }


@dataclass(frozen=True)
class ProvenanceEdge:
    """Derived record -> evidence root linkage."""

    derived_id: str
    evidence_root_sha256: str
    relation: str

    def to_canonical_dict(self) -> dict:
        return {
            "schema": "mios.provenance_edge",
            "derived_id": self.derived_id,
            "evidence_root_sha256": self.evidence_root_sha256,
            "relation": self.relation,
        }

src/mios/contracts/timestamps.py:
"""Point-in-time timestamp contract.

Laws: UTC internally, naive rejected (9); raw text + source timezone preserved (9);
precision never invented (10).
"""
from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timezone
from enum import Enum
from typing import Optional


class TimePrecision(Enum):
    SECOND = "second"
    MILLISECOND = "millisecond"
    MICROSECOND = "microsecond"
    NANOSECOND = "nanosecond"


PRECISION_RANK = {
    TimePrecision.SECOND: 0,
    TimePrecision.MILLISECOND: 1,
    TimePrecision.MICROSECOND: 2,
    TimePrecision.NANOSECOND: 3,
}


class NaiveTimestampError(ValueError):
    """A timezone-naive datetime attempted to enter the system."""


class PrecisionInventionError(ValueError):
    """A timestamp claims finer precision than its source supplied."""


@dataclass(frozen=True)
class PointInTimeTimestamp:
    """A UTC instant that preserves its original source representation."""

    utc: datetime
    precision: TimePrecision
    raw_text: Optional[str] = None
    source_timezone: Optional[str] = None

    def __post_init__(self) -> None:
        if self.utc.tzinfo is None or self.utc.tzinfo.utcoffset(self.utc) is None:
            raise NaiveTimestampError("naive datetime rejected: all timestamps must be timezone-aware")
        object.__setattr__(self, "utc", self.utc.astimezone(timezone.utc))
        if self.precision is TimePrecision.SECOND and self.utc.microsecond != 0:
            raise PrecisionInventionError("second-resolution source cannot carry sub-second digits")
        if self.precision is TimePrecision.MILLISECOND and self.utc.microsecond % 1000 != 0:
            raise PrecisionInventionError("millisecond-resolution source cannot carry microsecond digits")

    def to_canonical_dict(self) -> dict:
        return {
            "schema": "mios.timestamp",
            "utc": self.utc.isoformat(),
            "precision": self.precision.value,
            "raw_text": self.raw_text,
            "source_timezone": self.source_timezone,
        }

src/mios/guards/no_live_authority.py:
"""Runtime guard: prove broker SDKs and order-submission paths are absent (Law 14)."""
from __future__ import annotations

import os
import re
from typing import Dict, List

FORBIDDEN_IMPORTS = (
    "ib_insync", "ibapi", "alpaca", "alpaca_trade_api", "ccxt", "oandapyV20",
    "robin_stocks", "kiteconnect", "tda", "binance", "coinbase", "kraken",
)

_ORDER_SYMBOL = re.compile(
    r"def\s+(submit_live_order|place_live_order|send_live_order|execute_live_order)\b"
)


def scan_tree_for_live_authority(root: str) -> Dict:
    """Static scan of the source tree for broker SDK imports and live order symbols."""
    findings: List[Dict] = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in {".git", "__pycache__", "artifacts", ".venv"}]
        for fn in filenames:
            if not fn.endswith(".py") or fn == "no_live_authority.py":
                continue
            path = os.path.join(dirpath, fn)
            with open(path, encoding="utf-8", errors="replace") as fh:
                text = fh.read()
            for mod in FORBIDDEN_IMPORTS:
                if re.search(rf"^\s*(import|from)\s+{re.escape(mod)}\b", text, re.M):
                    findings.append({"file": path, "kind": "forbidden_broker_sdk", "detail": mod})
            match = _ORDER_SYMBOL.search(text)
            if match:
                findings.append({"file": path, "kind": "live_order_symbol", "detail": match.group(0)})
    return {"clean": not findings, "findings": findings}


def assert_package_exposes_no_live_order(package) -> None:
    """Importing the project must expose no live order function."""
    for name in dir(package):
        lowered = name.lower()
        if "order" in lowered and ("submit" in lowered or "place" in lowered or "send" in lowered):
            raise AssertionError(f"package exposes suspicious live-order symbol: {name}")

tools/secret_scan.py:
"""Regex + entropy secret scanner. Failures are gate failures."""
from __future__ import annotations

import math
import os
import re
from typing import Dict, List

PATTERNS = [
    ("aws_access_key", re.compile(r"AKIA[0-9A-Z]{16}")),
    ("private_key_block", re.compile(r"-----BEGIN (RSA |EC |OPENSSH )?PRIVATE KEY-----")),
    ("generic_api_key", re.compile(r"(?i)(api[_-]?key|secret|token|passwd|password)\s*[:=]\s*['\"][A-Za-z0-9+/_\-]{16,}['\"]")),
    ("bearer_token", re.compile(r"(?i)bearer\s+[a-z0-9\._\-]{20,}")),
    ("github_token", re.compile(r"gh[pousr]_[A-Za-z0-9]{30,}")),
]

def shannon_entropy(s: str) -> float:
    if not s:
        return 0.0
    freq = {c: s.count(c) for c in set(s)}
    return -sum((n / len(s)) * math.log2(n / len(s)) for n in freq.values())

def scan(root: str) -> Dict:
    findings: List[Dict] = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in {".git", "__pycache__", "artifacts", ".venv"}]
        for fn in filenames:
            path = os.path.join(dirpath, fn)
            try:
                with open(path, encoding="utf-8", errors="strict") as fh:
                    text = fh.read()
            except (UnicodeDecodeError, OSError):
                continue
            for name, pat in PATTERNS:
                for m in pat.finditer(text):
                    findings.append({"file": path, "kind": name, "match": m.group(0)[:24] + "..."})
    return {"clean": not findings, "findings": findings}

