            m.admit(prop("pa", requests_risk_approval=True), True, "v", "2026-01-05T00:00:00+00:00", "ma")
        with self.assertRaises(LLMAuthorityError):
            m.admit(prop("pb", requests_position_size=True), True, "v", "2026-01-05T00:00:00+00:00", "mb")


