"""Empirical probability calibration (Phase 7: PR-001..PR-003).

Displayed probabilities are EMPIRICAL, never raw model confidence (constitutional law 14).
"""
from __future__ import annotations

from dataclasses import dataclass
from math import sqrt
from typing import Dict, List, Optional, Sequence, Tuple


@dataclass(frozen=True)
class CalibrationBin:
    lower: float
    upper: float
    forecasts: int
    realized_rate: Optional[float]
    uncertainty: Optional[float]     # standard error of realized rate


class Calibrator:
    """Bins historical (forecast, outcome) pairs and answers with EMPIRICAL frequencies."""

    def __init__(self, n_bins: int = 10, min_samples_per_bin: int = 20, tolerance: float = 0.10) -> None:
        self._n = n_bins
        self._min = min_samples_per_bin
        self._tol = tolerance
        self._pairs: List[Tuple[float, int]] = []
        self._reference_mean: Optional[float] = None

    def observe(self, forecast: float, outcome: int) -> None:
        if not (0.0 <= forecast <= 1.0) or outcome not in (0, 1):
            raise ValueError("forecast in [0,1], outcome in {0,1}")
        self._pairs.append((forecast, outcome))
        if self._reference_mean is None and len(self._pairs) >= 100:
            self._reference_mean = sum(f for f, _ in self._pairs) / len(self._pairs)

    def bins(self) -> List[CalibrationBin]:
        out = []
        for k in range(self._n):
            lo, hi = k / self._n, (k + 1) / self._n
            hits = [(f, o) for f, o in self._pairs if lo <= f < hi or (k == self._n - 1 and f == 1.0)]
            if len(hits) >= self._min:
                rate = sum(o for _, o in hits) / len(hits)
                se = sqrt(rate * (1 - rate) / len(hits)) if len(hits) else None
                out.append(CalibrationBin(lo, hi, len(hits), round(rate, 4), round(se, 4) if se is not None else None))
            else:
                out.append(CalibrationBin(lo, hi, len(hits), None, None))
        return out

    def displayed_probability(self, raw_model_confidence: float) -> dict:
        """Returns the empirical calibrated probability WITH sample size and uncertainty (PR-002),
        or abstains when evidence is insufficient."""
        k = min(int(raw_model_confidence * self._n), self._n - 1)
        b = self.bins()[k]
        if b.realized_rate is None:
            return {"display": None, "abstain": True,
                    "reason": f"bin [{b.lower},{b.upper}) has only {b.forecasts} samples (<{self._min})",
                    "raw_confidence_never_displayed": True}
        return {"display": b.realized_rate, "sample_size": b.forecasts, "uncertainty": b.uncertainty,
                "abstain": False, "raw_confidence_never_displayed": True}

    def drift_check(self, recent: Sequence[float]) -> dict:
        """PR-003: distribution shift triggers downgrade/abstention/recalibration policy."""
        if self._reference_mean is None or not recent:
            return {"shift_detected": False, "action": "none"}
        recent_mean = sum(recent) / len(recent)
        if abs(recent_mean - self._reference_mean) > self._tol:
            return {"shift_detected": True, "action": "abstain_and_recalibrate",
                    "reference_mean": round(self._reference_mean, 4), "recent_mean": round(recent_mean, 4)}
        return {"shift_detected": False, "action": "none"}

src/mios/risk/risk_engine.py:
"""Deterministic risk engine: freshness, concentration, margin, kill switches, no-trade (Phase 7).

Risk decisions are deterministic and reproducible (law 9); independent from LLM output (law 8);
no-trade is a first-class action (law 10).
"""
from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass, field
from decimal import Decimal
from typing import Dict, List, Optional, Tuple


@dataclass(frozen=True)
class RiskPolicy:
    policy_id: str
    max_staleness_seconds: int
    max_correlated_exposure: Decimal      # combined exposure cap for one correlation group
    margin_usage_limit: Decimal           # fraction of margin capacity
    version: str = "1.0.0"

    def to_canonical_dict(self) -> dict:
        return {"policy_id": self.policy_id, "max_staleness_seconds": self.max_staleness_seconds,
                "max_correlated_exposure": str(self.max_correlated_exposure),
                "margin_usage_limit": str(self.margin_usage_limit), "version": self.version}


@dataclass(frozen=True)
class TradeIntentRequest:
    intent_id: str
    instrument_id: str
    side: str
    quantity: Decimal
    correlation_group: str
    is_risk_reducing: bool = False


@dataclass
class RiskState:
    data_age_seconds: int
    exposures_by_group: Dict[str, Decimal]
    margin_used: Decimal
    margin_capacity: Decimal
    kill_switches: Dict[str, bool] = field(default_factory=dict)   # global/venue/strategy/instrument


@dataclass(frozen=True)
class RiskDecision:
    intent_id: str
    action: str          # "approve" | "no_trade"
    reasons: Tuple[str, ...]
    policy_id: str
    decision_hash: str


class KillSwitchRegistry:
    """Deterministic, authenticated, logged kill switches (RS-004)."""

    def __init__(self, authorized_operators: Tuple[str, ...]) -> None:
        self._authorized = set(authorized_operators)
        self._states: Dict[str, bool] = {"global": False}
        self._log: List[dict] = []

    def set(self, scope: str, engaged: bool, operator: str) -> None:
        if operator not in self._authorized:
            raise PermissionError(f"operator '{operator}' is not authorized for kill switches")
        self._states[scope] = engaged
        self._log.append({"scope": scope, "engaged": engaged, "operator": operator, "seq": len(self._log) + 1})

    def engaged(self, scope: str) -> bool:
        return self._states.get("global", False) or self._states.get(scope, False)

    def log(self) -> List[dict]:
        return list(self._log)


def decide(req: TradeIntentRequest, state: RiskState, policy: RiskPolicy,
           kills: Optional[KillSwitchRegistry] = None) -> RiskDecision:
    reasons: List[str] = []

    if kills is not None and (kills.engaged("global") or kills.engaged(req.instrument_id)
                              or kills.engaged(req.correlation_group)):
        reasons.append("kill switch engaged")

    if state.data_age_seconds > policy.max_staleness_seconds:
        if req.is_risk_reducing:
            pass  # RS-001: risk-reducing actions remain possible on stale data
        else:
            reasons.append(f"stale data: {state.data_age_seconds}s > {policy.max_staleness_seconds}s; new entries blocked")

    group_exposure = state.exposures_by_group.get(req.correlation_group, Decimal("0"))
    if not req.is_risk_reducing and group_exposure + req.quantity > policy.max_correlated_exposure:
        reasons.append(
            f"correlated exposure {group_exposure}+{req.quantity} exceeds group cap {policy.max_correlated_exposure} (RS-002)")

    projected_margin = state.margin_used + req.quantity
    if not req.is_risk_reducing and projected_margin > state.margin_capacity * policy.margin_usage_limit:
        reasons.append("margin/liquidation threshold breach (RS-003)")

    action = "no_trade" if reasons else "approve"
    basis = {"intent": req.intent_id, "action": action, "reasons": reasons,
             "policy": policy.to_canonical_dict()}
    digest = hashlib.sha256(json.dumps(basis, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    return RiskDecision(req.intent_id, action, tuple(reasons), policy.policy_id, digest)


def gate_trade_intent(calibrated: dict, net_ev: dict, decision: RiskDecision) -> dict:
    """NT-001: inadequate evidence/calibration or negative net EV or risk breach => abstention, no TradeIntent."""
    if calibrated.get("abstain"):
        return {"trade_intent": None, "action": "no_trade", "reason": "calibration evidence insufficient (NT-001)"}
    if Decimal(net_ev["net_ev"]) <= 0:
        return {"trade_intent": None, "action": "no_trade", "reason": "net expected value non-positive (EV-002)"}
    if decision.action != "approve":
        return {"trade_intent": None, "action": "no_trade", "reason": "; ".join(decision.reasons)}
    return {"trade_intent": {"intent_id": decision.intent_id, "venue_neutral": True}, "action": "approve",
            "reason": "all gates passed"}

src/mios/execution/paper_broker.py:
"""Paper execution: venue-neutral TradeIntents -> capability-checked paper orders (Phase 8).

NO live authority: this module simulates a paper venue only. Broker adapters for IBKR/OANDA/Kraken
are ports with ENTITLEMENT_PENDING state (see broker_ports.py) — no SDK imports exist anywhere.
"""
from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass, field
from decimal import Decimal
from typing import Dict, List, Optional, Tuple


@dataclass(frozen=True)
class VenueCapabilities:
    venue_id: str
    supports_oco: bool
    supports_market: bool = True
    supports_limit: bool = True


class CapabilityError(RuntimeError):
    """The venue cannot natively express the requested order feature (EX-002: no silent emulation)."""


@dataclass(frozen=True)
class TradeIntent:
    intent_id: str
    instrument_id: str
    side: str
    quantity: Decimal
    order_type: str = "market"
    requires_oco: bool = False


class PaperLedger:
    """Append-only order/fill/position ledger; state is always reconstructable (EX-001)."""

    def __init__(self) -> None:
        self.entries: List[dict] = []

    def append(self, kind: str, data: dict) -> None:
        self.entries.append({"seq": len(self.entries) + 1, "kind": kind, **data})

    def reconstruct(self) -> dict:
        """Deterministic fold over the append-only ledger."""
        orders: Dict[str, dict] = {}
        position = Decimal("0")
        for e in self.entries:
            if e["kind"] == "order_accepted":
                orders[e["order_id"]] = {"remaining": Decimal(e["quantity"]), "status": "open",
                                         "side": e["side"]}
            elif e["kind"] == "fill":
                o = orders[e["order_id"]]
                qty = Decimal(e["quantity"])
                o["remaining"] -= qty
                position += qty if o["side"] == "buy" else -qty
                if o["remaining"] <= 0:
                    o["status"] = "filled"
                else:
                    o["status"] = "partially_filled"
            elif e["kind"] == "order_cancelled":
                orders[e["order_id"]]["status"] = "cancelled"
        state = {"orders": {k: {"remaining": str(v["remaining"]), "status": v["status"], "side": v["side"]}
                            for k, v in orders.items()},
                 "position": str(position)}
        state["state_hash"] = hashlib.sha256(json.dumps(state, sort_keys=True).encode()).hexdigest()
        return state


class PaperBroker:
    """Idempotent, capability-checked paper venue (EX-002/003)."""

    def __init__(self, capabilities: VenueCapabilities, ledger: PaperLedger) -> None:
        self._caps = capabilities
        self._ledger = ledger
        self._idempotency: Dict[str, str] = {}
        self._order_count = 0

    def submit_paper_order(self, intent: TradeIntent, idempotency_key: str) -> str:
        if intent.requires_oco and not self._caps.supports_oco:
            raise CapabilityError(
                f"venue {self._caps.venue_id} does not support native OCO; refusing silent emulation (EX-002)")
        if idempotency_key in self._idempotency:
            return self._idempotency[idempotency_key]      # EX-003: no duplicate order
        self._order_count += 1
        order_id = f"paper-{self._order_count:05d}"
        self._idempotency[idempotency_key] = order_id
        self._ledger.append("order_accepted", {"order_id": order_id, "intent_id": intent.intent_id,
                                               "side": intent.side, "quantity": str(intent.quantity),
                                               "venue": self._caps.venue_id, "mode": "PAPER"})
        return order_id

    def fill(self, order_id: str, quantity: Decimal, price: Decimal) -> None:
        self._ledger.append("fill", {"order_id": order_id, "quantity": str(quantity), "price": str(price)})


def reconcile(ledger_state: dict, venue_snapshot: dict) -> dict:
    """Continuous reconciliation between internal ledger and venue snapshot (law 13, EX-004)."""
    mismatches = []
    if ledger_state["position"] != venue_snapshot.get("position"):
        mismatches.append({"field": "position", "ledger": ledger_state["position"],
                           "venue": venue_snapshot.get("position")})
    for oid, o in ledger_state["orders"].items():
        v = venue_snapshot.get("orders", {}).get(oid)
        if v is None:
            if o["status"] in ("open", "partially_filled"):
                mismatches.append({"field": f"order:{oid}", "ledger": o["status"], "venue": "missing"})
        elif v["status"] != o["status"] or v.get("remaining") != o["remaining"]:
            mismatches.append({"field": f"order:{oid}", "ledger": o, "venue": v})
    return {"reconciled": not mismatches, "mismatches": mismatches}

src/mios/audit/audit_surface.py:
"""Auditable operator surface (Phase 10) — canonical read-only projection.

UI-001: every displayed metric deep-links to canonical lineage.
UI-002: the display layer cannot alter canonical calculations (read-only projections).
UI-003: role restrictions block unauthorized approvals/risk controls.
UI-004: fixture/shadow/paper/real source states cannot be visually confused (mandatory badges).
"""
from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from types import MappingProxyType
from typing import Any, Dict, List, Mapping, Optional

SOURCE_BADGES = {"fixture": "FIXTURE", "shadow": "SHADOW", "paper": "PAPER", "real": "REAL"}
ROLES = {"viewer": set(), "operator": {"approve_queue"}, "risk_officer": {"approve_queue", "kill_switch"}}


class RoleError(PermissionError):
    """Role lacks the attempted control action."""


@dataclass(frozen=True)
class DisplayMetric:
    metric_id: str
    label: str
    value: str
    source_state: str                 # fixture | shadow | paper | real
    lineage: Mapping[str, Any]        # event ids, versions, snapshot hash, policy ids

    def render(self) -> dict:
        if self.source_state not in SOURCE_BADGES:
            raise ValueError("unknown source state")
        if not self.lineage.get("event_versions") and not self.lineage.get("decision_id"):
            raise ValueError("metric refuses to render without lineage (UI-001)")
        return {
            "badge": SOURCE_BADGES[self.source_state],   # mandatory, non-optional badge (UI-004)
            "label": f"[{SOURCE_BADGES[self.source_state]}] {self.label}",
            "value": self.value,
            "deep_link": {"lineage": dict(self.lineage)},
        }


class AuditSurface:
    """Read-only projection over canonical results; mutation is structurally impossible (UI-002)."""

    def __init__(self, canonical_results: Dict[str, Any]) -> None:
        frozen = json.loads(json.dumps(canonical_results, sort_keys=True))
        self._canonical = MappingProxyType(frozen)
        self._canonical_hash = hashlib.sha256(
            json.dumps(frozen, sort_keys=True, separators=(",", ":")).encode()).hexdigest()

    @property
    def canonical(self) -> Mapping[str, Any]:
        return self._canonical

    def canonical_hash(self) -> str:
        return self._canonical_hash

    def act(self, role: str, action: str) -> str:
        allowed = ROLES.get(role, set())
        if action not in allowed:
            raise RoleError(f"role '{role}' may not perform '{action}' (UI-003)")
        return f"{action}:permitted"

tests/test_phase9_shadow.py:
"""Phase 9: SH-001..SH-005."""
from __future__ import annotations

import unittest

from mios.shadow.shadow_runner import OrderAuthorityViolation, ShadowRunner


def events(n=8):
    return [{"event_id": f"e-{i}", "is_data": True, "evidence_roots": ["d" * 64],
             "payload": {"price": 100 + i}} for i in range(n)]


def strategy(ev):
    return "would_enter" if ev["payload"]["price"] % 3 == 0 else "no_trade"


class SH001_ZeroOrderAuthority(unittest.TestCase):
    def test_no_broker_attachable(self):
        r = ShadowRunner()
        with self.assertRaises(OrderAuthorityViolation):
            r.broker = object()
        with self.assertRaises(AttributeError):
            r.some_random_attr = 1  # __slots__ prevents any extra state

    def test_no_submit_method_exists(self):
        r = ShadowRunner()
        self.assertFalse(hasattr(r, "submit_paper_order"))
        self.assertFalse(hasattr(r, "submit_order"))


class SH002_LineageReconstruction(unittest.TestCase):
    def test_every_decision_has_lineage(self):
        r = ShadowRunner()
        for d in r.run(events(), strategy):
            self.assertTrue(d.input_event_ids)
            self.assertTrue(d.evidence_roots)
            self.assertEqual(len(d.lineage_hash), 64)


class SH003_StaleHalts(unittest.TestCase):
    def test_stale_gap_produces_no_trade(self):
        evs = events(8)
        for i in range(2, 7):
            evs[i]["is_data"] = False   # 5 consecutive non-data heartbeats
        r = ShadowRunner(max_staleness_indices=3)
        ds = r.run(evs, strategy)
        stale = [d for d in ds if "stale data" in d.reasons[0]]
        self.assertTrue(stale)
        for d in stale:
            self.assertEqual(d.would_action, "no_trade")


class SH004_RestartNoDuplicates(unittest.TestCase):
    def test_catchup_skips_seen_events(self):
        evs = events(8)
        r = ShadowRunner()
        r.run(evs[:5], strategy)
        # 'restart replay catch-up': re-feed the full stream; seen events are skipped
        ds = r.run(evs, strategy)
        self.assertEqual(len(ds), 8)
        self.assertEqual(len({d.input_event_ids[0] for d in ds}), 8)


class SH005_ProviderReconnectRecovery(unittest.TestCase):
    def test_duplicate_events_after_reconnect(self):
        evs = events(4) + events(4)  # provider resends everything after reconnect
        r = ShadowRunner()
        ds = r.run(evs, strategy)
        self.assertEqual(len(ds), 4)  # no duplicate decisions


if __name__ == "__main__":
    unittest.main()

src/mios/hardening/integrity.py:
"""Backup/restore integrity and corruption quarantine (DR-001/002)."""
from __future__ import annotations

import base64
import hashlib
import json
from typing import Dict, List, Tuple

from ..storage.event_store import EventStore


def export_backup(store: EventStore) -> dict:
    """Deterministic logical backup of the canonical store."""
    events = [dict(r) for r in store.all_events()]
    incidents = [dict(r) for r in store.incidents()]
    raws = {}
    for e in events:
        raw = store.load_raw_bytes(e["raw_sha256"])
        if raw is not None:
            raws[e["raw_sha256"]] = base64.b64encode(raw).decode("ascii")
    body = {"events": events, "incidents": incidents, "raws": raws}
    digest = hashlib.sha256(json.dumps(body, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    return {"body": body, "backup_hash": digest}


def verify_backup(backup: dict) -> dict:
    """Detect and quarantine corrupted raw objects (DR-002)."""
    quarantined: List[str] = []
    for sha, b64 in backup["body"]["raws"].items():
        raw = base64.b64decode(b64)
        if hashlib.sha256(raw).hexdigest() != sha:
            quarantined.append(sha)
    return {"clean": not quarantined, "quarantined": quarantined}

src/mios/hardening/live_guard.py:
"""LIVE-000: no live-capital route exists or can be enabled by configuration alone."""
from __future__ import annotations

from typing import Mapping


class LiveAuthorityConfigError(PermissionError):
    """A configuration attempted to enable live trading. This is constitutionally impossible."""


FORBIDDEN_CONFIG_KEYS = ("live_trading", "enable_live", "live_orders", "production_orders", "real_money")


def validate_runtime_config(config: Mapping) -> Mapping:
    """Any configuration that even names a live-trading flag is rejected outright."""
    for key in config:
        lowered = str(key).lower()
        for forbidden in FORBIDDEN_CONFIG_KEYS:
            if forbidden in lowered:
                raise LiveAuthorityConfigError(
                    f"configuration key '{key}' attempts to reference live authority; "
                    "live capital requires a separate written authorization outside this codebase")
    return config

